parameters.jsCode:
const form = $('Sujet de l\'article').item.json
const raw = $input.item.json.content[0].text
let parsed
try { parsed = JSON.parse(raw) } catch (e) { throw new Error('Réponse Claude non-JSON : ' + raw.slice(0, 300)) }
const publishNow = /^oui/i.test(form['Publier immédiatement ? (oui / non)'] || '')
return [{
  json: {
    title: parsed.title,
    excerpt: parsed.excerpt,
    body: parsed.body,
    category: form['Catégorie (Acquisition / Pilotage IA / Web & applications / Stratégie)'],
    tags: parsed.tags || [],
    status: publishNow ? 'published' : 'draft'
  }
}]
